(6323915, 935816, 96751, '<td valign="top">I see what looks like a bush in the upper left, and this big round thing which seems to be trying to climb through a window.  Someone''s butt?</td>', 'I see what looks like a bush in the upper left, and this big round thing which seems to be trying to climb through a window.  Someone''s butt?', '2011-02-21 01:58:37.000000', NULL, 1),
(6323917, 936342, 96751, '<td valign="top">Sigh.  The sort of image I wish I had the talent to create and the courage to enter.</td>', 'Sigh.  The sort of image I wish I had the talent to create and the courage to enter.', '2011-02-21 01:59:12.000000', NULL, 1),
(6323918, 936576, 40391, '<td valign="top">First thought was hair but Im guessing this is some sort of course paper.  Probably home made.  Yes, I know, way off.</td>', 'First thought was hair but Im guessing this is some sort of course paper.  Probably home made.  Yes, I know, way off.', '2011-02-21 01:59:15.000000', NULL, 1),
