(6323922, 936450, 40391, '<td valign="top">Stilettos on a glass table top with wooden carvings inside?</td>', 'Stilettos on a glass table top with wooden carvings inside?', '2011-02-21 02:00:40.000000', NULL, 1),
(6323923, 936860, 96751, '<td valign="top">A landscape from the bottom of the ocean.  Incredible tones and light.</td>', 'A landscape from the bottom of the ocean.  Incredible tones and light.', '2011-02-21 02:00:45.000000', NULL, 1),
(6323924, 936863, 96751, '<td valign="top">Gorgeous lighting.</td>', 'Gorgeous lighting.', '2011-02-21 02:01:41.000000', NULL, 1),
(6323925, 936811, 96751, '<td valign="top">Didn''t even see the car that hit me.  Just was suddenly lying on the road, the white line disappearing into the distance, and my new goggles all smashed to heck.</td>', 'Didn''t even see the car that hit me.  Just was suddenly lying on the road, the white line disappearing into the distance, and my new goggles all smashed to heck.', '2011-02-21 02:02:55.000000', NULL, 1),
