(6325414, 936734, 81362, '<td valign="top">Maybe one of those popcorn wafer snacks? Would be interesting to see with side lighting to bring out the texture more.</td>', 'Maybe one of those popcorn wafer snacks? Would be interesting to see with side lighting to bring out the texture more.', '2011-02-21 18:30:40.000000', NULL, 1),
(6325416, 936786, 81362, '<td valign="top">Leaves make me think of a cork for a wine bottle. Good positining and lighting.</td>', 'Leaves make me think of a cork for a wine bottle. Good positining and lighting.', '2011-02-21 18:31:54.000000', NULL, 1),
(6325419, 936889, 81362, '<td valign="top">I once had a furnace filter that looked a lot like this, only much more dust. Blue goes well with white here.</td>', 'I once had a furnace filter that looked a lot like this, only much more dust. Blue goes well with white here.', '2011-02-21 18:32:50.000000', NULL, 1),
(6325420, 936750, 81362, '<td valign="top">Diffraction lens on a small flashlight? Very pretty with all the irregular directions the little lines take.</td>', 'Diffraction lens on a small flashlight? Very pretty with all the irregular directions the little lines take.', '2011-02-21 18:34:08.000000', NULL, 1),
(6325434, 936571, 81362, '<td valign="top">Looks like the tip of a corkscrew. Enjoying the variation in focus as well as the colorful background.</td>', 'Looks like the tip of a corkscrew. Enjoying the variation in focus as well as the colorful background.', '2011-02-21 18:46:05.000000', NULL, 1),
(6325436, 936592, 81362, '<td valign="top">Looks like spiral pasta to me. Centered symmetry works well with the repeating curves.</td>', 'Looks like spiral pasta to me. Centered symmetry works well with the repeating curves.', '2011-02-21 18:47:22.000000', NULL, 1),
(6325437, 936800, 81362, '<td valign="top">Could be the corner of a paper cutter (can be very handy to have when you need one).</td>', 'Could be the corner of a paper cutter (can be very handy to have when you need one).', '2011-02-21 18:49:10.000000', NULL, 1),
(6325438, 936769, 81362, '<td valign="top">Nice group of toothpick tips; Google brings up Twinkle Twinkle Patrick Star song associated with Sponge Bob show as having the phrase in it.</td>', 'Nice group of toothpick tips; Google brings up Twinkle Twinkle Patrick Star song associated with Sponge Bob show as having the phrase in it.', '2011-02-21 18:49:13.000000', NULL, 1),
(6325440, 936878, 81362, '<td valign="top">First thought was slice of a brain, but closer look makes me think of half a walnut or some sort of pastry layered with jelly then folded intricately and cooked.</td>', 'First thought was slice of a brain, but closer look makes me think of half a walnut or some sort of pastry layered with jelly then folded intricately and cooked.', '2011-02-21 18:52:21.000000', NULL, 1),
(6325442, 936538, 81362, '<td valign="top">Hedge trimmer blades have this shape. Will be interesting to find out what it is.</td>', 'Hedge trimmer blades have this shape. Will be interesting to find out what it is.', '2011-02-21 18:52:58.000000', NULL, 1),
(6325443, 936643, 81362, '<td valign="top">Looks like the end of a brush for applying makeup (guessing from the elegant handle that is nicely out of focuse). Good color and sharpness.</td>', 'Looks like the end of a brush for applying makeup (guessing from the elegant handle that is nicely out of focuse). Good color and sharpness.', '2011-02-21 18:54:55.000000', NULL, 1),
